//! Performance sessions: one per game run, with the FPS the game reported.
//!
//! The launcher records them, keeps them locally and sends them to the
//! server, which compares builders, versions and machines.

use std::collections::{BTreeMap, BTreeSet};

use serde::{Deserialize, Serialize};

/// Points kept of the FPS curve of a session.
pub const SERIES_POINTS: usize = 600;

/// What one run of a builder measured.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Session {
    /// Unique, generated by the launcher: sending twice stores once.
    pub id: String,
    pub builder: String,
    /// Commit that was running (short hash), empty when unknown.
    #[serde(default)]
    pub commit: String,
    /// Name given by the player to this machine (`machine_name` setting).
    #[serde(default)]
    pub machine: String,
    #[serde(default)]
    pub os: String,
    #[serde(default)]
    pub launcher: String,
    /// Unix time, seconds.
    pub started_at: u64,
    /// How long the game ran.
    pub duration_secs: f64,
    pub samples: u32,
    pub avg: f64,
    pub min: f64,
    pub max: f64,
    /// Average of the slowest 1 % of the samples.
    pub low1: f64,
    /// The FPS over time, at most `SERIES_POINTS` values.
    #[serde(default)]
    pub series: Vec<f32>,
    /// Everything else measured (`gpu`, `cpu`, `ram`, `proc_cpu`, `disk_read`…),
    /// by name. `fps` is in the fields above and here too.
    #[serde(default)]
    pub metrics: BTreeMap<String, Metric>,
    /// CPU, GPU and driver versions, memory, system.
    #[serde(default)]
    pub specs: Option<Specs>,
    /// The phases of the game, in order, each from its start.
    #[serde(default)]
    pub phases: Vec<Phase>,
}

/// A phase of the game (`menu`, `intro`…) and when it started.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Phase {
    pub name: String,
    /// Seconds since the game started.
    pub start: f64,
}

/// The machine a run was measured on.
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct Specs {
    pub cpu: String,
    pub cores: u32,
    pub threads: u32,
    pub ram_mb: u64,
    /// `Windows 11 Pro 23H2`, kernel included when the system gives it.
    pub os: String,
    pub gpus: Vec<Gpu>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct Gpu {
    pub name: String,
    pub driver: String,
    /// `YYYY-MM-DD`, empty when unknown.
    #[serde(default)]
    pub driver_date: String,
}

/// One measured quantity over a run.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Metric {
    pub samples: u32,
    pub avg: f64,
    pub min: f64,
    pub max: f64,
    /// 1st and 99th percentiles.
    pub p1: f64,
    pub p99: f64,
    /// Values over the run, evenly spaced, at most `SERIES_POINTS`.
    pub series: Vec<f32>,
}

impl Metric {
    pub fn from_samples(samples: &[(f64, f64)]) -> Option<Self> {
        let sum = summarize(samples)?;
        let mut v: Vec<f64> = samples.iter().map(|s| s.1).collect();
        v.sort_by(|a, b| a.total_cmp(b));
        let at = |q: f64| v[((v.len() - 1) as f64 * q).round() as usize];
        Some(Self {
            samples: sum.samples,
            avg: sum.avg,
            min: sum.min,
            max: sum.max,
            p1: at(0.01),
            p99: at(0.99),
            series: sum.series,
        })
    }
}

/// Numbers of a run, from `(seconds since start, fps)` samples.
#[derive(Debug, Clone, PartialEq)]
pub struct Summary {
    pub samples: u32,
    pub avg: f64,
    pub min: f64,
    pub max: f64,
    pub low1: f64,
    pub series: Vec<f32>,
}

pub fn summarize(samples: &[(f64, f64)]) -> Option<Summary> {
    if samples.is_empty() {
        return None;
    }
    let n = samples.len();
    let mut fps: Vec<f64> = samples.iter().map(|s| s.1).collect();
    let avg = fps.iter().sum::<f64>() / n as f64;
    fps.sort_by(|a, b| a.total_cmp(b));
    let worst = n.div_ceil(100).max(1);
    let low1 = fps[..worst].iter().sum::<f64>() / worst as f64;
    // Averages of equal slices keep the shape of the curve and drop the noise.
    let points = n.min(SERIES_POINTS);
    let series = (0..points)
        .map(|i| {
            let (a, b) = (i * n / points, (i + 1) * n / points);
            let slice = &samples[a..b.max(a + 1)];
            (slice.iter().map(|s| s.1).sum::<f64>() / slice.len() as f64) as f32
        })
        .collect();
    Some(Summary { samples: n as u32, avg, min: fps[0], max: fps[n - 1], low1, series })
}

/// How a builder at a given commit performs across every run reported.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Row {
    pub builder: String,
    pub commit: String,
    pub sessions: u32,
    pub machines: u32,
    /// Mean of the averages of the sessions.
    pub avg: f64,
    pub best_avg: f64,
    pub low1: f64,
    pub last_at: u64,
}

/// Groups sessions by builder and commit. Sorted by builder, then newest first.
pub fn aggregate(sessions: &[Session]) -> Vec<Row> {
    let mut groups: BTreeMap<(&str, &str), Vec<&Session>> = BTreeMap::new();
    for s in sessions.iter().filter(|s| s.samples > 0) {
        groups.entry((&s.builder, &s.commit)).or_default().push(s);
    }
    let mut rows: Vec<Row> = groups
        .into_iter()
        .map(|((builder, commit), g)| {
            let n = g.len() as f64;
            Row {
                builder: builder.to_string(),
                commit: commit.to_string(),
                sessions: g.len() as u32,
                machines: g.iter().map(|s| s.machine.as_str()).collect::<BTreeSet<_>>().len() as u32,
                avg: g.iter().map(|s| s.avg).sum::<f64>() / n,
                best_avg: g.iter().map(|s| s.avg).fold(0.0, f64::max),
                low1: g.iter().map(|s| s.low1).sum::<f64>() / n,
                last_at: g.iter().map(|s| s.started_at).max().unwrap_or(0),
            }
        })
        .collect();
    rows.sort_by(|a, b| a.builder.cmp(&b.builder).then(b.last_at.cmp(&a.last_at)));
    rows
}

/// How one metric behaved during one phase of a run.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct PhaseMetric {
    pub avg: f64,
    pub min: f64,
    pub max: f64,
    pub p1: f64,
}

/// One phase of one run, from its start to the start of the next.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct PhaseStat {
    pub name: String,
    pub start: f64,
    pub end: f64,
    pub metrics: BTreeMap<String, PhaseMetric>,
}

/// The phases of a run with the numbers of each: the series of every metric
/// are cut at the phase boundaries.
pub fn phase_stats(s: &Session) -> Vec<PhaseStat> {
    let metrics: BTreeMap<&str, &Metric> = if s.metrics.is_empty() && !s.series.is_empty() {
        BTreeMap::new()
    } else {
        s.metrics.iter().map(|(k, v)| (k.as_str(), v)).collect()
    };
    s.phases
        .iter()
        .enumerate()
        .map(|(i, p)| {
            let end = s.phases.get(i + 1).map_or(s.duration_secs, |n| n.start);
            let mut out = BTreeMap::new();
            for (name, m) in &metrics {
                let n = m.series.len();
                if n < 2 {
                    continue;
                }
                let dt = s.duration_secs / (n - 1) as f64;
                let mut v: Vec<f64> = m
                    .series
                    .iter()
                    .enumerate()
                    .filter(|(i, _)| (*i as f64 * dt) >= p.start && (*i as f64 * dt) < end)
                    .map(|(_, v)| *v as f64)
                    .filter(|v| v.is_finite())
                    .collect();
                if v.is_empty() {
                    continue;
                }
                v.sort_by(|a, b| a.total_cmp(b));
                let avg = v.iter().sum::<f64>() / v.len() as f64;
                let p1 = v[((v.len() - 1) as f64 * 0.01).round() as usize];
                out.insert(name.to_string(), PhaseMetric { avg, min: v[0], max: v[v.len() - 1], p1 });
            }
            PhaseStat { name: p.name.clone(), start: p.start, end, metrics: out }
        })
        .collect()
}

/// A phase compared across every run of a builder at a commit.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct PhaseRow {
    pub builder: String,
    pub commit: String,
    pub phase: String,
    pub sessions: u32,
    pub machines: u32,
    /// Mean time spent in the phase.
    pub secs: f64,
    /// Means over the runs of the averages of each metric of the phase.
    pub fps: f64,
    pub fps_low1: f64,
    pub frame_ms: f64,
    pub last_at: u64,
}

/// Groups the phases of all runs by builder, commit and phase name. Only
/// phases with FPS count: without them there is nothing to compare.
pub fn aggregate_phases(sessions: &[Session]) -> Vec<PhaseRow> {
    type Key = (String, String, String);
    let mut groups: BTreeMap<Key, Vec<(&Session, PhaseStat)>> = BTreeMap::new();
    for s in sessions {
        for p in phase_stats(s) {
            if p.metrics.contains_key("fps") {
                groups.entry((s.builder.clone(), s.commit.clone(), p.name.clone())).or_default().push((s, p));
            }
        }
    }
    let mean = |g: &[(&Session, PhaseStat)], f: &dyn Fn(&PhaseStat) -> Option<f64>| {
        let v: Vec<f64> = g.iter().filter_map(|(_, p)| f(p)).collect();
        if v.is_empty() { 0.0 } else { v.iter().sum::<f64>() / v.len() as f64 }
    };
    let mut rows: Vec<PhaseRow> = groups
        .into_iter()
        .map(|((builder, commit, phase), g)| PhaseRow {
            builder,
            commit,
            phase,
            sessions: g.len() as u32,
            machines: g.iter().map(|(s, _)| s.machine.as_str()).collect::<BTreeSet<_>>().len() as u32,
            secs: mean(&g, &|p| Some(p.end - p.start)),
            fps: mean(&g, &|p| p.metrics.get("fps").map(|m| m.avg)),
            fps_low1: mean(&g, &|p| p.metrics.get("fps").map(|m| m.p1)),
            frame_ms: mean(&g, &|p| p.metrics.get("frame_ms").map(|m| m.avg)),
            last_at: g.iter().map(|(s, _)| s.started_at).max().unwrap_or(0),
        })
        .collect();
    rows.sort_by(|a, b| a.phase.cmp(&b.phase).then(b.fps.total_cmp(&a.fps)));
    rows
}

/// What `GET /api/stats` answers.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct StatsReport {
    pub rows: Vec<Row>,
    /// The same, phase by phase (menu, intro, story…).
    #[serde(default)]
    pub phases: Vec<PhaseRow>,
    /// The newest sessions, newest first.
    pub recent: Vec<Session>,
}

impl Session {
    /// Refuses what a client should never send.
    pub fn validate(&self) -> Result<(), String> {
        let short = |s: &str| s.len() <= 100 && !s.contains(['\n', '\r']);
        if self.id.is_empty()
            || ![&self.id, &self.builder, &self.commit, &self.machine, &self.os, &self.launcher]
                .into_iter()
                .all(|s| short(s))
        {
            return Err("text field empty or too long".into());
        }
        if self.builder.is_empty() || (self.samples == 0 && self.metrics.is_empty()) {
            return Err("no samples".into());
        }
        if self.series.len() > SERIES_POINTS * 2 || self.metrics.len() > 40 {
            return Err("too many values".into());
        }
        if let Some(sp) = &self.specs {
            let texts = sp.gpus.iter().flat_map(|g| [&g.name, &g.driver, &g.driver_date]).chain([&sp.cpu, &sp.os]);
            if sp.gpus.len() > 8 || texts.into_iter().any(|t| t.len() > 200) {
                return Err("specs too long".into());
            }
        }
        if self.phases.len() > 500 || self.phases.iter().any(|p| p.name.len() > 100 || !p.start.is_finite()) {
            return Err("phases refused".into());
        }
        for (name, m) in &self.metrics {
            let n = [m.avg, m.min, m.max, m.p1, m.p99];
            if name.len() > 32 || m.series.len() > SERIES_POINTS * 2 || !n.into_iter().all(|v| v.is_finite()) {
                return Err(format!("metric {name:?} refused"));
            }
        }
        let ok = |v: f64| v.is_finite() && (0.0..=100_000.0).contains(&v);
        if ![self.avg, self.min, self.max, self.low1, self.duration_secs].into_iter().all(ok) {
            return Err("number out of range".into());
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn session(builder: &str, commit: &str, machine: &str, avg: f64, at: u64) -> Session {
        Session {
            id: format!("{builder}{commit}{machine}{at}"),
            builder: builder.into(),
            commit: commit.into(),
            machine: machine.into(),
            os: "windows".into(),
            launcher: "0.3.0".into(),
            started_at: at,
            duration_secs: 60.0,
            samples: 10,
            avg,
            min: avg / 2.0,
            max: avg * 2.0,
            low1: avg / 3.0,
            series: vec![],
            metrics: Default::default(),
            specs: None,
            phases: vec![],
        }
    }

    #[test]
    fn summary_numbers() {
        let s: Vec<(f64, f64)> = (0..200).map(|i| (i as f64, if i < 2 { 10.0 } else { 60.0 })).collect();
        let sum = summarize(&s).unwrap();
        assert_eq!(sum.samples, 200);
        assert_eq!((sum.min, sum.max), (10.0, 60.0));
        assert!((sum.avg - 59.5).abs() < 1e-9);
        // 1 % of 200 samples is 2 samples, both at 10.
        assert_eq!(sum.low1, 10.0);
        assert_eq!(sum.series.len(), 200);
        let m = Metric::from_samples(&s).unwrap();
        assert_eq!(m.p99, 60.0);
        assert!(m.p1 >= 10.0 && m.p1 <= 60.0);
        assert!(summarize(&[]).is_none());
    }

    #[test]
    fn aggregates_per_builder_and_commit() {
        let rows = aggregate(&[
            session("amd", "aaa", "pc1", 30.0, 1),
            session("amd", "aaa", "pc2", 50.0, 2),
            session("amd", "bbb", "pc1", 60.0, 3),
        ]);
        assert_eq!(rows.len(), 2);
        // Newest commit first.
        assert_eq!(rows[0].commit, "bbb");
        assert_eq!((rows[1].sessions, rows[1].machines), (2, 2));
        assert_eq!(rows[1].avg, 40.0);
        assert_eq!(rows[1].best_avg, 50.0);
    }

    fn phased() -> Session {
        // 11 FPS values, one per 10 s over 100 s: menu 0-30, story from 30.
        let mut s = session("amd", "aaa", "pc1", 30.0, 1);
        s.duration_secs = 100.0;
        let fps: Vec<f32> = [5, 5, 5, 40, 40, 40, 40, 40, 40, 40, 40].map(|v| v as f32).to_vec();
        let m = Metric { samples: 11, avg: 0.0, min: 5.0, max: 40.0, p1: 5.0, p99: 40.0, series: fps };
        s.metrics.insert("fps".into(), m);
        s.phases = vec![Phase { name: "menu".into(), start: 0.0 }, Phase { name: "story".into(), start: 30.0 }];
        s
    }

    #[test]
    fn stats_per_phase() {
        let p = phase_stats(&phased());
        assert_eq!(p.len(), 2);
        assert_eq!((p[0].start, p[0].end), (0.0, 30.0));
        assert_eq!(p[0].metrics["fps"].avg, 5.0);
        assert_eq!(p[1].metrics["fps"].avg, 40.0);
        assert_eq!(p[1].end, 100.0);
    }

    #[test]
    fn phases_compared_across_runs() {
        let mut slow = phased();
        slow.id = "slow".into();
        slow.machine = "pc2".into();
        slow.metrics.get_mut("fps").unwrap().series = vec![5.0; 11];
        let rows = aggregate_phases(&[phased(), slow]);
        let story = rows.iter().find(|r| r.phase == "story").unwrap();
        assert_eq!((story.sessions, story.machines), (2, 2));
        assert_eq!(story.fps, 22.5);
        assert_eq!(rows.iter().filter(|r| r.phase == "menu").count(), 1);
        assert!(aggregate_phases(&[session("a", "b", "c", 1.0, 1)]).is_empty(), "no phases, no rows");
    }

    #[test]
    fn validation() {
        let mut s = session("amd", "aaa", "pc1", 30.0, 1);
        assert!(s.validate().is_ok());
        s.avg = f64::NAN;
        assert!(s.validate().is_err());
        let mut s = session("amd", "aaa", "pc1", 30.0, 1);
        s.machine = "x".repeat(200);
        assert!(s.validate().is_err());
    }
}
